// The six step views. Each reads from the API and draws; no number is calculated here.
const head = (run, title) => [h("h1", {}, title), h("p", { class: "muted" }, run.name + " · ", h("code", {}, run.id))];
const go = (run, step) => { location.hash = `#/run/${run.id}/${step}`; };
const button = (label, onclick, plain) => h("button", { onclick, class: plain ? "plain" : "" }, label);

async function uploadStep(run) {
  const rows = (files) => table(["File", "State", "Contract"], files.map((f) => [h("code", {}, f.name),
    f.present && !f.error ? h("span", { class: "ok" }, `ok (${f.bytes} bytes)`) :
      h("span", { class: "bad" }, f.present ? "rejected" : "missing"), f.error || ""]));
  const input = h("input", { type: "file", multiple: true });
  const upload = async () => {
    const results = [];
    for (const file of input.files) {
      try {
        const r = await api("PUT", `/runs/${run.id}/files/${encodeURIComponent(file.name)}`, undefined, await file.arrayBuffer());
        if (!r.stored) results.push(`${file.name}: ${r.error}`);
      } catch (e) { results.push(`${file.name}: ${e.message}`); }
    }
    await uploadStep(run);
    results.forEach((t) => view.prepend(h("div", { class: "error" }, t)));
  };
  const fresh = await api("GET", `/runs/${run.id}`);
  const ready = fresh.files.every((f) => f.present && !f.error);
  const next = async () => { try { await api("POST", `/runs/${run.id}/analyse`); go(run, "review"); } catch (e) { fail(e); } };
  show(...head(run, "1 Upload"), h("div", { class: "callout" }, "Only the 15 expected file names are accepted, up to 1 MB each. " +
    "A file that breaks its contract is refused and the reason is shown on its row."),
    h("div", { class: "row" }, input, button("Upload", upload)), rows(fresh.files),
    h("div", { class: "row" }, h("button", { onclick: next, disabled: !ready }, "Analyse and go to Review")));
}

async function reviewStep(run) {
  if (run.status === "new") {
    return show(...head(run, "2 Review"), h("p", {}, "This run has not been analysed yet."),
      button("Analyse", async () => { try { await api("POST", `/runs/${run.id}/analyse`); await route(); } catch (e) { fail(e); } }));
  }
  const rv = await api("GET", `/runs/${run.id}/review`);
  const marks = {};
  const approver = h("input", { placeholder: "your name", maxlength: 60, "aria-label": "Your name" });
  const cardKeys = new Set(rv.cards.map((c) => c.key));
  const others = rv.queue.filter((q) => rv.open_items.includes(q.key) && !cardKeys.has(q.key));
  const send = async () => {
    const decisions = Object.fromEntries(Object.entries(marks).filter(([, v]) => v));
    try { await api("POST", `/runs/${run.id}/decisions`, { approver: approver.value, decisions }); await route(); }
    catch (e) { fail(e); }
  };
  const holder = h("div");
  const draw = () => holder.replaceChildren(...issueGroups(rv.cards, marks, draw));
  draw();
  show(...head(run, "2 Review"), h("p", {}, "Status: ", h("span", { class: "tag" }, run.status)),
    rv.open_items.length ? h("div", { class: "callout warn" }, `${rv.open_items.length} item(s) wait for a decision. Approve or reject each card, add your name and submit.`) :
      h("div", { class: "callout ok" }, "Nothing is waiting for a decision."),
    others.length ? h("div", {}, h("h2", {}, "Other items waiting"), table(["Item", "State", "Reason"], others.map((q) => [h("code", {}, q.key), q.state, q.reason]))) : null,
    holder,
    rv.open_items.length ? h("div", { class: "row" }, approver, button("Submit decisions", send)) : null,
    h("h2", {}, "Journal dispositions"),
    table(["Journal", "Disposition", "Reasons"], rv.dispositions.map((d) => [d.journal_id, d.status, d.reasons.join("; ")])),
    aiPanel(rv.ai),
    h("div", { class: "row" }, button("Next: choose outputs", () => go(run, "outputs"))));
}

async function outputsStep(run) {
  const out = await api("GET", `/runs/${run.id}/outputs`);
  const picked = new Set(out.chosen || out.available.map((o) => o.name));
  const boxes = out.available.map((o) => h("input", { type: "checkbox", checked: picked.has(o.name), disabled: o.required,
    onchange: (e) => (e.target.checked ? picked.add(o.name) : picked.delete(o.name)) }));
  const save = async () => { try { await api("PUT", `/runs/${run.id}/outputs`, { files: [...picked] }); go(run, "build"); } catch (e) { fail(e); } };
  show(...head(run, "3 Choose outputs"), h("p", { class: "muted" }, "The run manifest is always included."),
    table(["", "File", "Bytes"], out.available.map((o, i) => [boxes[i], h("code", {}, o.name), o.bytes])),
    h("div", { class: "row" }, button("Save and build", save)));
}

async function buildStep(run) {
  const b = await api("POST", `/runs/${run.id}/build`);
  show(...head(run, "4 Build"), h("div", { class: b.passed ? "callout ok" : "error" },
    b.passed ? `All ${b.gates.length} gates passed.` : "A gate failed" + (b.blocked ? `: ${b.blocked}` : ".")),
    h("h2", {}, "Stages this run logged"), stageList(b.stages), h("h2", {}, `Gates (${b.gates.length})`),
    table(["Gate", "Result", "Detail"], b.gates.map((g) => [g.name, h("span", { class: g.ok ? "ok" : "bad" }, g.ok ? "pass" : "FAIL"), tidy(g.detail)])),
    h("div", { class: "row" }, button("Next: results", () => go(run, "results"))));
}

async function resultsStep(run) {
  const r = await api("GET", `/runs/${run.id}/results`);
  const others = (await api("GET", "/runs")).filter((x) => x.id !== run.id && x.status === "done");
  const f = Object.fromEntries(["line", "column", "value"].map((k) => [k, h("input", { placeholder: k, size: k === "value" ? 14 : 10 })]));
  f.file = h("select", {}, ["fx_rates.csv", "tb_uk.csv", "tb_us.csv", "tb_in.csv", "intercompany.csv", "subledger_controls.csv"].map((n) => h("option", {}, n)));
  const name = h("input", { placeholder: "name for the new run" });
  const build = async () => {
    try {
      const n = await api("POST", `/runs/${run.id}/whatif`, { name: name.value, patches: [`${f.file.value}:${f.line.value}.${f.column.value}=${f.value.value}`] });
      go(n, "results");
    } catch (e) { fail(e); }
  };
  const other = h("select", {}, [h("option", { value: "" }, "choose a run")].concat(others.map((o) => h("option", { value: o.id }, `${o.name} (${o.id})`))));
  const holder = h("div");
  const compare = async () => {
    if (!other.value) return;
    try {
      const c = await api("GET", `/runs/${run.id}/compare/${other.value}`);
      holder.replaceChildren(h("h2", {}, "Input changes"), h("ul", {}, (c.input_changes.length ? c.input_changes : ["identical inputs"]).map((t) => h("li", {}, t))),
        h("h2", {}, "What each changed line feeds (1% nudge)"),
        table(["Line", "Figures that move"], Object.entries(c.impact).map(([t, m]) => [h("code", {}, t), Object.entries(m).map(([k, v]) => `${k}: ${amount(v.before)} → ${amount(v.after)}`).join("; ") || "none"])),
        h("h2", {}, "Figures that differ"), table(["Figure", "Other run", "This run"], c.figures.map((x) => [x.key, figureValue({ value: x.other }), figureValue({ value: x.this })])));
    } catch (e) { fail(e); }
  };
  show(...head(run, "5 Results"), h("h2", {}, "The 12 control figures"),
    figuresTable(r.figures),
    h("h2", {}, `Issues (${r.issues.length})`), ...issueGroups(r.cards, {}, () => {}),
    h("h2", {}, "What if an input changes?"), h("p", { class: "muted" }, "Builds a new run from a changed cell (line 1 is the header); this run is left as it is."),
    h("div", { class: "row" }, f.file, f.line, f.column, f.value, name, button("Build new run", build)),
    h("h2", {}, "Compare with another run"), h("div", { class: "row" }, other, button("Compare", compare, true)), holder,
    h("div", { class: "row" }, button("Next: output files", () => go(run, "files"))));
}

async function exportStep(run) {
  const out = await api("GET", `/runs/${run.id}/outputs`);
  const names = out.chosen ? [...out.chosen, "run_manifest.json"] : out.available.map((o) => o.name);
  show(...head(run, "7 Export"), h("p", {}, "A zip of the chosen files plus the run manifest:"),
    h("ul", {}, [...new Set(names)].map((n) => h("li", {}, h("code", {}, n)))),
    h("a", { class: "btn", href: `/api/runs/${run.id}/export` }, "Download zip"));
}

const STEP_VIEWS = { upload: uploadStep, review: reviewStep, outputs: outputsStep, build: buildStep, results: resultsStep, files: filesStep, export: exportStep };
"""Run the two reviewers over every unit: replay or record the model answer, ground each claim, and fall back to the
rule-based proposer when no usable answer exists. The result is advice (policy 2): it never changes a figure."""
from dataclasses import dataclass

from app.agents.journal_reviewer.llm_model import review_journal
from app.agents.mapping_reviewer.llm_model import review_mapping
from app.domain.runs import Context
from app.llm.client import Mode
from app.llm.factory import LlmConfig
from app.llm.ledger import Ledger, LlmStop, LlmUnavailable
from app.review.fallback import journal_by_rules, mapping_by_rules
from app.review.grounding import Grounded, ground_journal, ground_mapping, journal_facts, mapping_facts
from app.review.units import Unit, journal_units, mapping_units


@dataclass(frozen=True)
class UnitResult:
    unit: Unit
    source: str  # "model" or "rules"
    grounded: Grounded
    note: str = ""
    missed: tuple[str, ...] = ()  # exact facts the model did not report: it disagrees with the rules


def coa_view(ctx: Context) -> dict[str, dict[str, str]]:
    return {c: {"name": a.name, "statement": a.statement} for c, a in ctx.inputs.coa.items()}


def review_unit(ctx: Context, cfg: LlmConfig, ledger: Ledger, unit: Unit, mode: Mode = "replay") -> UnitResult:
    coa = coa_view(ctx)
    try:
        if unit.kind == "journal":
            grounded = ground_journal(review_journal(cfg, ledger, unit.packet, mode), unit.packet)
            facts = journal_facts(unit.packet)
        else:
            mapping = review_mapping(cfg, ledger, unit.packet, tuple(sorted(coa)), mode)
            grounded = ground_mapping(mapping, unit.packet, coa)
            facts = {"sign_unusual": mapping_facts(unit.packet, coa)[0]["sign_unusual"]}
        missed = tuple(k for k, v in facts.items() if v and k not in grounded.verified)
        return UnitResult(unit, "model", grounded, missed=missed)
    except LlmUnavailable as why:
        if unit.kind == "journal":
            return UnitResult(unit, "rules", ground_journal(journal_by_rules(unit.packet), unit.packet), str(why))
        return UnitResult(unit, "rules", ground_mapping(mapping_by_rules(unit.packet, coa), unit.packet, coa), str(why))


class BatchStopped(Exception):
    """A live batch ended early (a bad key, no credit or the circuit breaker). Keeps what was finished."""

    def __init__(self, reason: str, done: list[UnitResult], left: int) -> None:
        super().__init__(reason)
        self.reason, self.done, self.left = reason, done, left


def review_all(ctx: Context, cfg: LlmConfig, ledger: Ledger, mode: Mode = "replay") -> list[UnitResult]:
    units = mapping_units(ctx) + journal_units(ctx)
    done: list[UnitResult] = []
    for unit in units:
        try:
            done.append(review_unit(ctx, cfg, ledger, unit, mode))
        except LlmStop as stop:
            raise BatchStopped(str(stop), done, len(units) - len(done)) from stop
    return done
"""Human decisions on findings: which overrides apply, which are stale, and the review queue."""
import re
from dataclasses import dataclass
from pathlib import Path

from app.domain.findings import Finding
from app.domain.policy import Override
from app.domain.runs import Inputs
from app.parsers.mappings import classify_all
from app.utils.hashing import json_hash


@dataclass(frozen=True)
class OverrideState:
    """`applied` and `open` change the run; `stale` and `rejected` do not."""

    override: Override
    state: str


def evidence_hash(inputs: Inputs, target: str) -> str | None:
    """What the reviewer looked at: the mapping row and the trial balance row of 'mapping:UK:2310'."""
    kind, entity, code = target.split(":")
    if kind != "mapping":
        return None
    for line in classify_all(inputs.trial_balances, inputs.maps, inputs.coa):
        if (line.line.entity, line.line.local_code) == (entity, code) and line.map_ref is not None:
            return json_hash([line.map_ref.row_hash, line.line.ref.row_hash])
    return None


def override_states(rows: list[Override], inputs: Inputs) -> list[OverrideState]:
    """A decision made on evidence that has since changed is stale: it stops applying and returns to the queue."""
    states = []
    for row in rows:
        if row.status == "rejected":
            states.append(OverrideState(row, "rejected"))
        elif row.evidence_hash != evidence_hash(inputs, row.target):
            states.append(OverrideState(row, "stale"))
        else:
            states.append(OverrideState(row, "applied" if row.status == "approved" else "open"))
    return states


def active_overrides(rows: list[Override], inputs: Inputs) -> list[Override]:
    return [s.override for s in override_states(rows, inputs) if s.state in {"applied", "open"}]


def review_queue(findings: list[Finding], states: list[OverrideState]) -> list[dict[str, str]]:
    """Open and stale overrides first, then every finding a person still has to look at. Notes are not queued."""
    queue = [{"kind": "override", "key": s.override.target, "state": s.state, "reason": s.override.reason}
             for s in states if s.state in {"open", "stale"}]
    for f in findings:
        mapping_decided = f.code == "D02" and f.action == "assumed" and bool(states)
        if f.severity != "NOTE" and not mapping_decided:
            queue.append({"kind": "finding", "key": f.key, "state": f.action, "reason": f.claim})
    return queue


def approve(path: Path, inputs: Inputs, target: str, approver: str) -> None:
    """Sign a decision off on the evidence as it stands now: sets approver, status and evidence_hash in the file."""
    _rewrite(path, target, {"approver": approver, "status": "approved", "evidence_hash": evidence_hash(inputs, target)})


def reject(path: Path, target: str, approver: str) -> None:
    _rewrite(path, target, {"approver": approver, "status": "rejected"})


def _rewrite(path: Path, target: str, fields: dict[str, str | None]) -> None:
    text = path.read_text(encoding="utf-8")
    blocks = re.split(r"(?m)^(?=\[\[override\]\])", text)
    for i, block in enumerate(blocks):
        if f'target = "{target}"' not in block:
            continue
        for name, value in fields.items():
            line = f'{name} = "{value}"'
            pattern = rf'(?m)^{name} = ".*"$'
            block = re.sub(pattern, line, block) if re.search(pattern, block) else block.rstrip("\n") + f"\n{line}\n"
        blocks[i] = block
        path.write_text("".join(blocks), encoding="utf-8", newline="")
        return
    raise KeyError(f"no override for {target}")
"""Run registry, upload, review and build endpoints. Each calls one existing service."""
from typing import Annotated, Any

from fastapi import APIRouter, Depends, HTTPException, Request

from app.api_models import Decisions, NewRun
from app.services import pipeline_service as pipeline
from app.services.registry_service import Registry
from app.services.upload_service import EXPECTED_FILES, MAX_BYTES, file_status, validate_bytes

router = APIRouter(prefix="/api")


def registry(request: Request) -> Registry:
    reg: Registry = request.app.state.registry
    return reg


Reg = Annotated[Registry, Depends(registry)]


@router.get("/runs")
def list_runs(reg: Reg) -> list[dict[str, Any]]:
    return reg.list()


@router.post("/runs")
def create_run(body: NewRun, reg: Reg) -> dict[str, Any]:
    return reg.create(body.name, body.use_sample)


@router.get("/runs/{run_id}")
def open_run(run_id: str, reg: Reg) -> dict[str, Any]:
    return reg.meta(run_id) | {"files": file_status(reg.data_dir(run_id))}


@router.put("/runs/{run_id}/files/{name}")
async def upload(run_id: str, name: str, request: Request, reg: Reg) -> dict[str, Any]:
    """The body is the raw file. It is checked against its contract in a scratch copy, then stored only if it passes."""
    if name not in EXPECTED_FILES:
        raise HTTPException(422, f"{name} is not one of the 15 expected files")
    folder = reg.data_dir(run_id)
    body = await request.body()
    if len(body) > MAX_BYTES:
        raise HTTPException(413, f"{name} is larger than {MAX_BYTES} bytes")
    error = validate_bytes(name, body)
    if error is None:
        (folder / name).write_bytes(body)
    return {"name": name, "stored": error is None, "error": error}


@router.post("/runs/{run_id}/analyse")
def analyse(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.analyse(reg, run_id)


@router.get("/runs/{run_id}/review")
def review(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.review_view(reg, run_id)


@router.post("/runs/{run_id}/decisions")
def decide(run_id: str, body: Decisions, reg: Reg) -> dict[str, Any]:
    return pipeline.decide(reg, run_id, body.approver, body.decisions)


@router.post("/runs/{run_id}/build")
def build(run_id: str, reg: Reg) -> dict[str, Any]:
    return pipeline.build(reg, run_id)
