"""The steps behind the UI, each a thin call into an existing service: analyse and resume go through the same graph
the command line uses, review advice is replayed from the ledger only, and the gates are the engine's own checks."""
import json
from pathlib import Path
from typing import Any

from app.config import load_overrides
from app.llm.factory import load_llm_config
from app.llm.ledger import Ledger
from app.orchestrator.graph import resume_graph, run_graph, thread_for
from app.orchestrator.state import RunState
from app.services import ai_service
from app.services.cards_service import build_cards
from app.services.overrides_service import override_states, review_queue
from app.services.registry_service import Registry
from app.services.review_service import review_all
from app.services.run_service import Consolidation, build_context, stage
from app.services.upload_service import file_status


class NotReady(Exception):
    """The step cannot run yet. The message says what is missing."""


def _checkpoints(registry: Registry, run_id: str) -> Path:
    return registry.folder(run_id) / "checkpoints.db"


def _store(registry: Registry, run_id: str, state: RunState) -> dict[str, Any]:
    return registry.update(run_id, status=state["status"], open_items=state.get("open_items", []),
                           blocked=state.get("blocked"), checks_passed=state.get("checks_passed"))


def analyse(registry: Registry, run_id: str) -> dict[str, Any]:
    bad = [r["name"] for r in file_status(registry.data_dir(run_id)) if not r["present"] or r["error"]]
    if bad:
        raise NotReady("fix or upload these files first: " + ", ".join(str(n) for n in bad))
    thread = thread_for(registry.data_dir(run_id), registry.config_dir(run_id))
    registry.update(run_id, thread=thread)
    return _store(registry, run_id, run_graph(registry.state(run_id), _checkpoints(registry, run_id)))


def decide(registry: Registry, run_id: str, approver: str, decisions: dict[str, str]) -> dict[str, Any]:
    meta = registry.meta(run_id)
    if meta["status"] != "awaiting_review":
        raise NotReady("this run is not waiting for a decision")
    unknown = sorted(set(decisions) - set(meta["open_items"]))
    if unknown:
        raise NotReady("not open for decision: " + ", ".join(unknown))
    answer = {"approver": approver, "decisions": decisions}
    return _store(registry, run_id, resume_graph(meta["thread"], answer, _checkpoints(registry, run_id)))


def _advice(registry: Registry, run_id: str) -> list[dict[str, Any]]:
    """Recorded model advice. 'replay' never calls a model: a unit with no recorded answer reads 'not recorded'."""
    ctx = build_context(registry.data_dir(run_id), registry.config_dir(run_id))
    cfg = load_llm_config()
    rows = []
    for r in review_all(ctx, cfg, Ledger(cfg.ledger_path), "replay"):
        if r.grounded.verified or r.grounded.unverified or r.grounded.dropped or r.missed:
            rows.append({"kind": r.unit.kind, "unit": r.unit.unit_id, "source": r.source,
                         "recorded": r.source == "model", "verified": list(r.grounded.verified),
                         "unverified": list(r.grounded.unverified), "missed": list(r.missed),
                         "dropped": [{"claim": c, "why": w} for c, w in r.grounded.dropped]})
    return rows


def _memos(run: Consolidation) -> dict[str, dict[str, Any]]:
    """Text addressed to tools (D12), tied to the journal starting last at or before its line."""
    starts = sorted((j.ref.line, j.id) for j in run.ctx.inputs.journals)
    found = {}
    for f in run.findings:
        if f.code == "D12" and f.quoted_text is not None and f.line is not None:
            owner = [jid for line, jid in starts if line <= f.line]
            if owner:
                found[owner[-1]] = {"line": f.line, "text": f.quoted_text.text}
    return found


def review_view(registry: Registry, run_id: str) -> dict[str, Any]:
    ctx = build_context(registry.data_dir(run_id), registry.config_dir(run_id))
    run = stage(ctx)
    states = override_states(load_overrides(registry.config_dir(run_id) / "overrides.toml"), ctx.inputs)
    keep = ("key", "code", "severity", "claim", "file", "line", "action", "subject")
    findings = [{k: v for k, v in f.model_dump(mode="json").items() if k in keep} for f in run.findings]
    dispositions = [d.model_dump(mode="json") for d in run.dispositions]
    open_items = registry.meta(run_id)["open_items"]
    ai = ai_service.review_units(registry, run_id)
    units = ai["units"]
    return {
        "ai": ai, "findings": findings, "cards": build_cards(findings, units, dispositions, open_items, _memos(run)),
        "dispositions": dispositions,
        "queue": review_queue(run.findings, states),
        "open_items": open_items,
        "advice": _advice(registry, run_id),
    }


def build(registry: Registry, run_id: str) -> dict[str, Any]:
    """The gates are the engine's own invariant and oracle checks, run again on this run's files."""
    if registry.meta(run_id)["status"] != "done":
        raise NotReady("decide the open items first: the run has not finished")
    run = stage(build_context(registry.data_dir(run_id), registry.config_dir(run_id)))
    registry.update(run_id, built=True)
    gates = [{"name": c.name, "ok": c.ok, "detail": c.detail} for c in run.checks]
    return {"gates": gates, "passed": run.checks_passed, "blocked": run.blocked, "stages": run_log(registry, run_id)}


def result_cards(registry: Registry, run_id: str, items: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Cards for a finished run's issues.json rows: the same wording as the review step, with no decision buttons."""
    run = stage(build_context(registry.data_dir(run_id), registry.config_dir(run_id)))
    units = ai_service.review_units(registry, run_id)["units"]
    return build_cards(items, units, [d.model_dump(mode="json") for d in run.dispositions], [], _memos(run))


def run_log(registry: Registry, run_id: str) -> list[dict[str, Any]]:
    """The stages this run really logged, oldest first, without file paths."""
    events = []
    for path in sorted((registry.folder(run_id) / "logs").glob("*.jsonl")):
        for line in path.read_text(encoding="utf-8").splitlines():
            row = json.loads(line)
            events.append({k: v for k, v in row.items() if k not in {"run_id", "data_dir", "folder"}})
    return sorted(events, key=lambda e: str(e["ts"]))
// Issue cards. The wording comes from the server (cards_service); this file only lays it out.
const SEVERITY = { BLOCK: ["Blocking", "bad"], FLAG: ["Flagged", "warn"], NOTE: ["Noted", "muted"] };
const AI_STATE = { agrees: "AI agrees", disagrees: "AI disagrees", no_claim: "AI raised no claim", not_reviewed: "Not reviewed" };

function field(label, ...body) { return h("div", { class: "field" }, h("dt", {}, label), h("dd", {}, ...body)); }

function issueCard(card, marks, refresh) {
  const [sevText, sevClass] = SEVERITY[card.severity];
  const where = card.evidence.line == null ? card.evidence.file : `${card.evidence.file}, line ${card.evidence.line}`;
  const choose = (action) => () => { marks[card.key] = marks[card.key] === action ? undefined : action; refresh(); };
  const buttons = card.actions.map((a) => h("button", { class: marks[card.key] === a ? "" : "plain", "aria-pressed": String(marks[card.key] === a),
    onclick: choose(a) }, a === "approve" ? "Approve" : "Reject"));
  return h("article", { class: `card sev-${sevClass}` },
    h("div", { class: "card-head" }, h("span", { class: `tag ${sevClass}` }, sevText), h("code", { title: "detector code" }, card.code)),
    h("h3", {}, card.headline),
    h("dl", {}, field("Evidence", where), card.quote ? field("The text, quoted as data", h("q", {}, card.quote)) : null,
      field("What the rules decided", card.rules),
      field("What the AI reviewer said", h("span", { class: `tag ai-${card.ai.state}` }, AI_STATE[card.ai.state]), " ", card.ai.text),
      card.dropped.length ? field("Claims dropped by grounding", h("ul", {}, card.dropped.map((d) => h("li", {}, h("code", {}, d.claim), ": ", d.why)))) : null),
    buttons.length ? h("div", { class: "row" }, ...buttons, h("span", { class: "muted small" }, "Needs your decision")) : null);
}

// Cards grouped by what needs a decision, then by severity.
function issueGroups(cards, marks, refresh) {
  const groups = [["Needs your decision", cards.filter((c) => c.needs_decision)]];
  for (const sev of ["BLOCK", "FLAG", "NOTE"]) {
    groups.push([`${SEVERITY[sev][0]}, decided by the rules`, cards.filter((c) => !c.needs_decision && c.severity === sev)]);
  }
  if (!cards.length) return [h("div", { class: "callout ok" }, "No issues were found.")];
  return groups.filter(([, list]) => list.length).map(([title, list]) =>
    h("section", {}, h("h2", {}, `${title} (${list.length})`), list.map((c) => issueCard(c, marks, refresh))));
}
// Review UI: hash router, API helper and the runs list. Everything from the server is put on the page with
// text nodes (never as HTML), so uploaded text is shown as data and cannot run as script.
const STEPS = [["upload", "1 Upload"], ["review", "2 Review"], ["outputs", "3 Choose outputs"],
               ["build", "4 Build"], ["results", "5 Results"], ["files", "6 Output files"], ["export", "7 Export"]];
const view = document.getElementById("view");
const stepper = document.getElementById("stepper");

function h(tag, attrs = {}, ...kids) {
  const el = document.createElement(tag);
  for (const [k, v] of Object.entries(attrs)) {
    if (k.startsWith("on")) el.addEventListener(k.slice(2), v);
    else if (v === true) el.setAttribute(k, "");
    else if (v !== false && v != null) el.setAttribute(k, v);
  }
  for (const kid of kids.flat()) if (kid != null) el.append(kid.nodeType ? kid : String(kid));
  return el;
}

async function api(method, path, body, raw) {
  const init = { method, headers: {} };
  if (raw !== undefined) init.body = raw;
  else if (body !== undefined) { init.body = JSON.stringify(body); init.headers["Content-Type"] = "application/json"; }
  const res = await fetch("/api" + path, init);
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(typeof data.detail === "string" ? data.detail : JSON.stringify(data.detail || res.status));
  return data;
}

function show(...nodes) { view.replaceChildren(...nodes.filter((n) => n != null)); }
function fail(error) { view.prepend(h("div", { class: "error" }, String(error.message || error))); }
function table(head, rows) {
  return h("table", {}, h("thead", {}, h("tr", {}, head.map((t) => h("th", {}, t)))),
           h("tbody", {}, rows.map((r) => h("tr", {}, r.map((c) => h("td", {}, c))))));
}
function when(text) { return new Date(text).toLocaleString(); }

const STATUS = { new: "Not analysed", awaiting_review: "Waiting for a decision", done: "Finished", blocked: "Blocked" };

// One state per step, from what the run already holds: nothing here is a guess about work not done.
function stepState(run, key, step) {
  const finished = run.status === "done", analysed = run.status !== "new";
  if (key === step) return "current";
  if (run.blocked && key === "review") return "blocked";
  const done = { upload: analysed, review: finished, outputs: Boolean(run.outputs), build: Boolean(run.built), results: false, files: false, export: false }[key];
  if (done) return "done";
  if (key === "review" && run.status === "awaiting_review") return "blocked";
  const locked = { review: !analysed, outputs: !finished, build: !finished, results: !finished, files: !finished, export: !finished }[key];
  return locked ? "locked" : "todo";
}
const STATE_TEXT = { done: "Done", current: "Current", blocked: "Needs you", locked: "Not yet", todo: "Ready" };

function drawStepper(run, step) {
  const runbar = document.getElementById("runbar");
  if (!run) { stepper.replaceChildren(); runbar.replaceChildren(h("span", {}, "Review a consolidation run step by step")); return; }
  const at = STEPS.findIndex(([k]) => k === step);
  runbar.replaceChildren(h("strong", {}, run.name), h("span", { class: "tag" }, STATUS[run.blocked ? "blocked" : run.status] || run.status),
    h("span", {}, `Step ${at + 1} of ${STEPS.length}: ${STEPS[at][1].slice(2)}`));
  stepper.replaceChildren(...STEPS.map(([key, label], i) => {
    const state = stepState(run, key, step);
    const mark = state === "done" ? "\u2713" : state === "blocked" ? "!" : String(i + 1);
    return h(state === "locked" ? "span" : "a", { href: state === "locked" ? null : `#/run/${run.id}/${key}`, class: `item ${state}`,
      "aria-current": state === "current" ? "step" : null },
      h("span", { class: "dot", "aria-hidden": "true" }, mark),
      h("span", {}, label.slice(2), h("span", { class: "state" }, STATE_TEXT[state])));
  }));
}

function nextStep(run) {
  return { new: "upload", awaiting_review: "review", done: "results" }[run.status] || "review";
}

async function runsList() {
  drawStepper(null);
  const runs = await api("GET", "/runs");
  const name = h("input", { placeholder: "run name", maxlength: 60 });
  const sample = h("input", { type: "checkbox" });
  const create = async () => {
    try {
      const run = await api("POST", "/runs", { name: name.value, use_sample: sample.checked });
      location.hash = `#/run/${run.id}/upload`;
    } catch (e) { fail(e); }
  };
  show(h("h1", {}, "Runs"),
    h("div", { class: "row" }, name, h("label", {}, sample, " start with the supplied sample files"),
      h("button", { onclick: create }, "New run")),
    runs.length ? table(["Name", "Id", "Status", "Created", "Based on", ""], runs.map((r) => [
      r.name, h("code", {}, r.id), h("span", { class: "tag" }, r.status), when(r.created), r.parent || "",
      h("a", { class: "btn plain", href: `#/run/${r.id}/${nextStep(r)}` },
        r.status === "awaiting_review" ? "Resume" : "Open")])) : h("p", { class: "muted" }, "No runs yet."));
}

// A step that needs a finished run says why it cannot open yet and what to do, instead of showing an error.
function holdBack(run, step) {
  if (["upload", "review"].includes(step) || run.status === "done") return null;
  const to = (key, label) => h("a", { class: "btn", href: `#/run/${run.id}/${key}` }, label);
  if (run.blocked) return [h("h1", {}, "This run is blocked"), h("div", { class: "callout bad" }, run.blocked), to("review", "Open the review")];
  if (run.status === "awaiting_review") {
    return [h("h1", {}, "This run is paused"), h("div", { class: "callout warn" }, `${run.open_items.length} item(s) wait for a decision. ` +
      "Nothing after the review can run until each is approved or rejected and the decisions are submitted."), to("review", "Go to the review")];
  }
  return [h("h1", {}, "This run has not been analysed"), h("div", { class: "callout" }, "Upload the 15 files, or start from the sample, then analyse them."), to("upload", "Go to upload")];
}

async function route() {
  const [, kind, id, step] = location.hash.split("/");
  try {
    if (kind !== "run") return await runsList();
    const run = await api("GET", `/runs/${id}`);
    const chosen = STEPS.some(([k]) => k === step) ? step : nextStep(run);
    drawStepper(run, chosen);
    const waiting = holdBack(run, chosen);
    if (waiting) return show(...waiting);
    show(h("p", { role: "status", class: "muted" }, "Loading…"));
    await STEP_VIEWS[chosen](run);
  } catch (e) {
    show(h("div", { class: "error", role: "alert" }, String(e.message || e)),
      h("div", { class: "row" }, h("button", { onclick: route }, "Try again"), h("a", { class: "btn plain", href: "#/" }, "Back to runs")));
  }
}
window.addEventListener("hashchange", route);
"""Issue cards: each finding in plain English, from its own data. Nothing is invented: the headline reuses the finding's
claim with its numbers tidied, the rules text comes from its action and the journal's disposition, and the AI line comes
from the recorded review of the same journal or account. A finding with no matching unit reads 'not reviewed'."""
import re
from typing import Any

AMOUNT = re.compile(r"(?<![\w.])(\d{4,})\.(\d{2})\b")
ENTITY_CODE = re.compile(r"\b(UK|US|IN) ([A-Z0-9-]{3,})\b")
JOURNAL = re.compile(r"\bJE-\d+\b")
RULES = {
    "blocked": "Blocked by the rules: the item is not used until a person decides.",
    "assumed": "The rules applied a stated assumption and carried on.",
    "flagged": "Flagged by the rules: the figures stay as supplied and the issue is reported.",
    "noted": "Noted by the rules: no figure changed.",
}
DISPOSITION = {"POST": "posted", "REJECT": "rejected and not posted", "HOLD": "held for a person to decide"}
ORDER = {"BLOCK": 0, "FLAG": 1, "NOTE": 2}
FIGURE_NAMES = {
    "group_revenue": "Group revenue", "group_profit": "Group profit", "profit_owners": "Profit attributable to owners",
    "profit_nci": "Profit attributable to non-controlling interest", "nci_closing": "Closing non-controlling interest",
    "goodwill_closing": "Closing goodwill", "translation_reserve_movement": "Translation reserve movement",
    "total_assets": "Total assets", "total_equity": "Total equity",
    "intercompany_difference": "Intercompany difference",
    "sgd_bank_gbp": "The Singapore dollar bank balance in GBP", "journals": "The journal counts",
}
FIGURE_CLAIM = re.compile(r"^(\w+) is (provisional|null) ")


def plain(text: str) -> str:
    """1985000.00 -> 1,985,000 ; 23010.55 -> 23,010.55. Dates, rates and account codes have no cents part and stay."""
    def one(m: re.Match[str]) -> str:
        whole = f"{int(m[1]):,}"
        return whole if m[2] == "00" else f"{whole}.{m[2]}"
    return AMOUNT.sub(one, text)


def _subject(item: dict[str, Any]) -> str | None:
    found = JOURNAL.search(item["claim"])
    return item.get("subject") or (found.group(0) if found else None)


def _unit_for(item: dict[str, Any], units: list[dict[str, Any]]) -> dict[str, Any] | None:
    subject = _subject(item)
    if subject:
        return next((u for u in units if u["unit"] == subject), None)
    match = ENTITY_CODE.search(item["claim"])
    return next((u for u in units if match and u["unit"].startswith(f"{match[1]}:{match[2]}:")), None)


def _ai(unit: dict[str, Any] | None) -> dict[str, str]:
    if unit is None:
        return {"state": "not_reviewed",
                "text": "Not reviewed by the AI: it looks only at trial-balance mappings and journals."}
    if not unit["recorded"]:
        return {"state": "not_reviewed", "text": "No recorded AI answer here; the rule-based proposer was used."}
    if unit["missed"]:
        said = ", ".join(unit["missed"])
        return {"state": "disagrees", "text": f"The recorded AI answer did not report {said}, which the rules found."}
    if unit["verified"]:
        said = ", ".join(unit["verified"])
        return {"state": "agrees", "text": f"The recorded AI answer agrees and the packet backs it: {said}."}
    return {"state": "no_claim", "text": "The AI reviewed this item and raised no claim."}


def _figure(item: dict[str, Any]) -> str | None:
    found = FIGURE_CLAIM.match(item["claim"]) if item["code"] == "FIG" else None
    return found[1] if found and found[1] in FIGURE_NAMES else None


def _memo_note(memo: dict[str, Any]) -> str:
    """Say what the memo asks only when its own words say so; otherwise just that it is addressed to reviewers."""
    asks = re.search(r"skip.{0,40}check", memo["text"], re.IGNORECASE)
    return ("; its memo on line %d asks reviewers to skip the check and is treated as data" if asks
            else "; its memo on line %d is addressed to automated reviewers and is treated as data") % memo["line"]


def _headline(item: dict[str, Any], memos: dict[str, dict[str, Any]]) -> str:
    text = plain(item["claim"]).replace(" is unbalanced", " does not balance")
    figure = FIGURE_CLAIM.match(text)
    if item["code"] == "FIG" and figure and figure[1] in FIGURE_NAMES:
        verb = "is provisional" if figure[2] == "provisional" else "cannot be determined"
        text = f"{FIGURE_NAMES[figure[1]]} {verb}" + text[figure.end():]
    if item["code"] == "D12":
        owner = next((j for j, m in memos.items() if m["line"] == item["line"]), None)
        where = f"{item['file']} line {item['line']}" + (f" ({owner})" if owner else "")
        text = f"Text addressed to automated tools was found in {where}; it is treated as data and not obeyed"
    elif item["code"] == "D03" and _subject(item) in memos:
        text += _memo_note(memos[str(_subject(item))])
    return text[0].upper() + text[1:]


def build_cards(items: list[dict[str, Any]], units: list[dict[str, Any]], dispositions: list[dict[str, Any]],
                open_items: list[str], memos: dict[str, dict[str, Any]]) -> list[dict[str, Any]]:
    decided = {d["journal_id"]: d for d in dispositions}
    cards = []
    for item in items:
        unit, subject = _unit_for(item, units), _subject(item)
        rules = RULES[item["action"]]
        if subject in decided:
            rules += f" {subject} is {DISPOSITION[decided[subject]['status']]}."
        needs = item.get("key") in open_items
        cards.append({
            "key": item.get("key"), "figure": _figure(item), "code": item["code"], "severity": item["severity"],
            "headline": _headline(item, memos),
            "evidence": {"file": item["file"], "line": item.get("line")}, "rules": rules, "ai": _ai(unit),
            "quote": next((m["text"] for m in memos.values() if item["code"] == "D12" and m["line"] == item["line"]),
                          None),
            "dropped": unit["dropped"] if unit else [], "needs_decision": needs,
            "actions": ["approve", "reject"] if needs else [],
        })
    return sorted(cards, key=lambda c: (not c["needs_decision"], ORDER[c["severity"]]))
