"""One function per stage, shared by the LangGraph graph and the plain runner. Each returns a partial state update.

A node rebuilds what it needs from the files named in the state (the whole run takes about 20 ms), so nothing large
has to be checkpointed and a resumed process starts from the same bytes."""
from pathlib import Path
from typing import Any

from app.config import load_overrides
from app.detectors.registry import run_all
from app.orchestrator.state import RunState
from app.services.overrides_service import approve, override_states, reject
from app.services.run_service import build_context, input_hash, record, stage, write_outputs
from app.utils.hashing import sha256_file
from app.utils.logging import RunLogger

Answer = dict[str, Any]


def _log(state: RunState, stage_name: str, event: str, **fields: object) -> None:
    log = RunLogger(Path(state["log_dir"]), state["run_id"])
    log.event(stage_name, event, **fields)
    log.close()


def intake(state: RunState) -> RunState:
    run_id = input_hash(Path(state["data_dir"]), Path(state["config_dir"]))[:16]
    update = RunState(run_id=run_id, status="intake")
    _log(RunState(**{**state, **update}), "intake", "inputs read", data_dir=state["data_dir"])
    return update


def analyse(state: RunState) -> RunState:
    """Run the detectors and list the overrides a person still has to sign off or re-decide."""
    ctx = build_context(Path(state["data_dir"]), Path(state["config_dir"]))
    findings = run_all(ctx)
    states = override_states(load_overrides(Path(state["config_dir"]) / "overrides.toml"), ctx.inputs)
    waiting = [s.override.target for s in states if s.state in {"open", "stale"}]
    _log(state, "analyse", "findings", count=len(findings), waiting=waiting)
    return RunState(status="analysed", open_items=waiting)


def apply_answer(state: RunState, answer: Answer) -> RunState:
    """A person's answer: {'approver': name, 'decisions': {target: 'approve' | 'reject'}}. The rest stay open."""
    config_dir = Path(state["config_dir"])
    inputs = build_context(Path(state["data_dir"]), config_dir).inputs
    decided: list[str] = []
    for target in state.get("open_items", []):
        choice = answer.get("decisions", {}).get(target)
        if choice == "approve":
            approve(config_dir / "overrides.toml", inputs, target, answer["approver"])
        elif choice == "reject":
            reject(config_dir / "overrides.toml", target, answer["approver"])
        else:
            continue
        decided.append(target)
    remaining = [t for t in state.get("open_items", []) if t not in decided]
    _log(state, "resolve", "answered", decided=decided, approver=answer.get("approver"))
    return RunState(status="resolved", open_items=remaining, decided=decided)


def consolidate(state: RunState) -> RunState:
    run = stage(build_context(Path(state["data_dir"]), Path(state["config_dir"])))
    _log(state, "consolidate", "done", blocked=run.blocked, checks_passed=run.checks_passed)
    return RunState(status="consolidated", blocked=run.blocked, checks_passed=run.checks_passed)


def export(state: RunState) -> RunState:
    config_dir, out_dir = Path(state["config_dir"]), Path(state["out_dir"])
    run = stage(build_context(Path(state["data_dir"]), config_dir))
    write_outputs(run, out_dir, config_dir)
"""Results, what-if, compare, output choice and export endpoints."""
from typing import Any

from fastapi import APIRouter, HTTPException, Response

from app.api_models import Outputs, WhatIf
from app.routes import Reg
from app.services import output_service as files
from app.services import pipeline_service as pipeline
from app.services import results_service as results
from app.services.pipeline_service import NotReady
from app.services.whatif_service import Change, patched_copy

router = APIRouter(prefix="/api")


def _finished(reg: Reg, run_id: str) -> None:
    if reg.meta(run_id)["status"] != "done":
        raise NotReady("the run has not finished")


@router.get("/runs/{run_id}/results")
def get_results(run_id: str, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    out = reg.out_dir(run_id)
    items = results.issues(out)
    return {"figures": results.figures(out), "issues": items, "cards": pipeline.result_cards(reg, run_id, items)}


@router.get("/runs/{run_id}/outputs")
def get_outputs(run_id: str, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    return {"available": results.available_outputs(reg.out_dir(run_id)), "chosen": reg.meta(run_id)["outputs"]}


@router.put("/runs/{run_id}/outputs")
def choose_outputs(run_id: str, body: Outputs, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    results.build_zip(reg.out_dir(run_id), body.files)
    return reg.update(run_id, outputs=body.files)


@router.post("/runs/{run_id}/whatif")
def whatif(run_id: str, body: WhatIf, reg: Reg) -> dict[str, Any]:
    """A changed input becomes a new run beside the old one; the old run is never touched."""
    parent = reg.meta(run_id)
    new = reg.create(body.name or f"what-if on {parent['name']}", parent=run_id,
                     copy_config_from=reg.config_dir(run_id))
    try:
        patched_copy(reg.data_dir(run_id), reg.data_dir(new["id"]), Change(body.patches, body.appends))
    except (ValueError, IndexError, KeyError, OSError) as error:
        raise HTTPException(422, f"change could not be applied: {error}") from error
    return pipeline.analyse(reg, new["id"])


@router.get("/runs/{run_id}/compare/{other_id}")
def compare(run_id: str, other_id: str, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    _finished(reg, other_id)
    return results.compare(reg, run_id, other_id)


@router.get("/runs/{run_id}/export")
def export(run_id: str, reg: Reg) -> Response:
    _finished(reg, run_id)
    chosen = reg.meta(run_id)["outputs"] or [o["name"] for o in results.available_outputs(reg.out_dir(run_id))]
    return Response(results.build_zip(reg.out_dir(run_id), chosen), media_type="application/zip",
                    headers={"Content-Disposition": f'attachment; filename="{run_id}.zip"'})


@router.get("/runs/{run_id}/output-files")
def output_files(run_id: str, reg: Reg) -> list[dict[str, Any]]:
    _finished(reg, run_id)
    return files.file_list(reg.out_dir(run_id))


@router.get("/runs/{run_id}/output-files/{name}")
def output_file(run_id: str, name: str, reg: Reg) -> dict[str, Any]:
    _finished(reg, run_id)
    try:
        return files.file_view(reg.out_dir(run_id), name)
    except files.TooLarge as error:
        raise HTTPException(413, str(error)) from error


@router.get("/runs/{run_id}/output-files/{name}/issues")
def output_file_issues(run_id: str, name: str, reg: Reg) -> dict[str, list[dict[str, Any]]]:
    _finished(reg, run_id)
    out = reg.out_dir(run_id)
    cards = pipeline.result_cards(reg, run_id, results.issues(out))
    return files.issues_by_file(out, cards, name)


@router.get("/runs/{run_id}/output-files/{name}/download")
def output_download(run_id: str, name: str, reg: Reg) -> Response:
    _finished(reg, run_id)
    out = reg.out_dir(run_id)
    if name not in {o["name"] for o in results.available_outputs(out)}:
        raise HTTPException(404, f"not an output of this run: {name}")
    return Response((out / name).read_bytes(), media_type="application/octet-stream",
                    headers={"Content-Disposition": f'attachment; filename="{name}"'})
"""Read a finished run's output files for the UI, compare two runs, and zip the chosen files. Nothing is recomputed:
the figures are the ones in control_figures_pb.json and control_figures_status.json."""
import io
import json
import re
import zipfile
from pathlib import Path
from typing import Any

from app.services.registry_service import Registry
from app.services.run_service import OUTPUT_FILES
from app.services.whatif_service import diff_inputs, impact

ALWAYS = "run_manifest.json"
CHANGED = re.compile(r"^(?P<file>[^:]+): changed at line\(s\) (?P<lines>.+)$")
MAX_IMPACT_TARGETS = 10


def _json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def figures(out_dir: Path) -> list[dict[str, Any]]:
    """The 12 figures with their status. A null carries the reason it is null (or the open items it rests on)."""
    values = _json(out_dir / "control_figures_pb.json")
    status = _json(out_dir / "control_figures_status.json")["figures"]
    return [{"key": key, "value": value, **status.get(key, {})} for key, value in values.items()]


def issues(out_dir: Path) -> list[dict[str, Any]]:
    return list(_json(out_dir / "issues.json")["issues"])


def available_outputs(out_dir: Path) -> list[dict[str, Any]]:
    names = [*OUTPUT_FILES, ALWAYS]
    return [{"name": n, "bytes": (out_dir / n).stat().st_size, "required": n == ALWAYS}
            for n in names if (out_dir / n).is_file()]


def build_zip(out_dir: Path, chosen: list[str]) -> bytes:
    """The chosen files plus the run manifest, which is always included. Only names that exist in the run's output
    folder are accepted, so a request cannot reach any other file."""
    allowed = {o["name"] for o in available_outputs(out_dir)}
    unknown = sorted(set(chosen) - allowed)
    if unknown:
        raise ValueError("not an output of this run: " + ", ".join(unknown))
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, "w", zipfile.ZIP_DEFLATED) as archive:
        for name in sorted({*chosen, ALWAYS} & allowed):
            archive.write(out_dir / name, name)
    return buffer.getvalue()


def _targets(changes: list[str]) -> list[str]:
    found = []
    for text in changes:
        match = CHANGED.match(text)
        if match and match["file"].endswith(".csv"):
            found += [f"{match['file']}:{n.strip()}" for n in match["lines"].split(",") if n.strip().isdigit()]
    return found[:MAX_IMPACT_TARGETS]


def compare(registry: Registry, run_id: str, other_id: str) -> dict[str, Any]:
    """This run against another: which input lines differ, what each changed CSV line feeds (measured by nudging it
    1%), and the figures side by side."""
    data, baseline = registry.data_dir(run_id), registry.data_dir(other_id)
    changes = diff_inputs(baseline, data)
    measured = {}
    for target in _targets(changes):
        try:
            diff = impact(data, target, registry.config_dir(run_id))
            measured[target] = {k: {"before": a, "after": b} for k, (a, b) in diff.figures.items()}
        except (ValueError, IndexError, KeyError):
            measured[target] = {}
    before, after = figures(registry.out_dir(other_id)), figures(registry.out_dir(run_id))
    moved = [{"key": a["key"], "other": b["value"], "this": a["value"]}
             for a, b in zip(after, before, strict=True) if a["value"] != b["value"]]
    return {"input_changes": changes, "impact": measured, "figures": moved}

